import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.bijRUqYl.js";const d=JSON.parse('{"title":"医疗健康与药店提示词模板","description":"医疗健康与药店场景的提示词模板：健康科普、患者沟通、用药提醒、随访。含合规红线提醒。","frontmatter":{"title":"医疗健康与药店提示词模板","description":"医疗健康与药店场景的提示词模板：健康科普、患者沟通、用药提醒、随访。含合规红线提醒。"},"headers":[],"relativePath":"community/prompts/医疗健康.md","filePath":"community/prompts/医疗健康.md"}'),e={name:"community/prompts/医疗健康.md"};function o(l,s,i,r,c,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="💊-医疗健康与药店-·-5-条提示词模板" tabindex="-1">💊 医疗健康与药店 · 5 条提示词模板 <a class="header-anchor" href="#💊-医疗健康与药店-·-5-条提示词模板" aria-label="Permalink to &quot;💊 医疗健康与药店 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>⚠️ <strong>先看这一段，再看模板。</strong> 医疗健康是<strong>唯一一个&quot;用错 AI 会出事&quot;的行业</strong>。所以这一页的规矩比其他页严： <strong>AI 在这里只能帮你&quot;把话说清楚&quot;，不能帮你&quot;做判断&quot;。</strong> 诊断、处方、用药方案、剂量——<strong>一个字都不能由 AI 定</strong>。 页面里的每条模板我都加了限制句，<strong>请不要删掉它们</strong>。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是【岗位：药师 / 护士 / 诊所运营 / 健康科普作者】，面对的是【患者 / 顾客 / 读者】。</span></span>
<span class="line"><span>帮我产出【科普稿 / 沟通话术 / 提醒文案】，形式【…】。</span></span>
<span class="line"><span>规矩：不做诊断、不给用药建议、不评估病情、不承诺疗效；信息只能来自我提供的资料。</span></span></code></pre></div><hr><h2 id="_1-·-健康科普内容-面向公众-不诊断" tabindex="-1">1 · 健康科普内容（面向公众，不诊断） <a class="header-anchor" href="#_1-·-健康科普内容-面向公众-不诊断" aria-label="Permalink to &quot;1 · 健康科普内容（面向公众，不诊断）&quot;">​</a></h2><p><strong>什么时候用</strong>：药店/诊所/健康号要发科普内容，但一不小心就越界变成&quot;给建议&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要写一篇科普，主题：【例如&quot;高血压患者日常要注意什么&quot;】</span></span>
<span class="line"><span>发布渠道：【门店海报 / 公众号 / 微信群 / 短视频口播稿】</span></span>
<span class="line"><span>长度：【…】</span></span>
<span class="line"><span>我这边有的权威资料来源：【粘贴或写明出处，例如某官方科普平台的公开文章】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写初稿，要求：</span></span>
<span class="line"><span>① 只做&quot;知识普及&quot;，不做&quot;个体建议&quot;，全部用&quot;一般来说/部分人&quot;这种表述</span></span>
<span class="line"><span>② 结构：是什么 → 常见误区 → 日常可以注意什么 → **什么情况必须去看医生**</span></span>
<span class="line"><span>③ 最后一段固定是&quot;出现以下情况请及时就医&quot;，并留出让我填本地医院信息的位置</span></span>
<span class="line"><span>④ 单独列一份&quot;风险词清单&quot;：这篇稿子里哪些句子如果发出去可能被理解成医疗建议</span></span>
<span class="line"><span>规矩：不许写治愈率、有效率、疗程、替代治疗方案；不许出现具体药品的推荐用法用量；不许编权威出处。</span></span></code></pre></div><p><strong>它给你</strong>：一份安全边界的科普稿 + 风险句自查清单。</p><hr><h2 id="_2-·-患者-顾客沟通话术-把专业话变人话" tabindex="-1">2 · 患者 / 顾客沟通话术（把专业话变人话） <a class="header-anchor" href="#_2-·-患者-顾客沟通话术-把专业话变人话" aria-label="Permalink to &quot;2 · 患者 / 顾客沟通话术（把专业话变人话）&quot;">​</a></h2><p><strong>什么时候用</strong>：你解释了三遍，对方还是没懂，而且开始不耐烦。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要跟【患者 / 家属 / 顾客】解释的是：【用你能接受的方式写清楚，例如&quot;这个检查是干什么的&quot;&quot;为什么要复查&quot;】</span></span>
<span class="line"><span>对方的理解程度：【…】，情绪状态：【着急 / 怀疑 / 害怕 / 无所谓】</span></span>
<span class="line"><span>我不能说 / 不能承诺的：【…】</span></span>
<span class="line"><span>必须让他记住的 2 件事：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一段解释（口语，适合当面说，200 字内）：</span></span>
<span class="line"><span>① 先用一个生活化的类比让他有画面</span></span>
<span class="line"><span>② 再说&quot;所以我们要做的是……&quot;</span></span>
<span class="line"><span>③ 最后确认式提问（让他复述一遍，确认真的听懂了）</span></span>
<span class="line"><span>另外给我：对方说出&quot;我在网上看到……&quot;的时候，我该怎么接。</span></span>
<span class="line"><span>规矩：不做诊断解释、不判断病情轻重；不承诺疗效和结果；所有医学细节必须是我提供的。</span></span></code></pre></div><p><strong>它给你</strong>：一段类比式解释 + 应对&quot;网上说&quot;的话术。</p><hr><h2 id="_3-·-用药提醒-依从性提醒文案" tabindex="-1">3 · 用药提醒 / 依从性提醒文案 <a class="header-anchor" href="#_3-·-用药提醒-依从性提醒文案" aria-label="Permalink to &quot;3 · 用药提醒 / 依从性提醒文案&quot;">​</a></h2><p><strong>什么时候用</strong>：要提醒顾客按时用药、复查、测指标，但你说多了像推销，说少了没人当回事。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提醒场景：【例如&quot;慢病患者配药后 7 天回访&quot;】</span></span>
<span class="line"><span>对象：【…】，之前的配合情况：【…】</span></span>
<span class="line"><span>我要提醒的具体事项清单：【由你（专业人员）填写，AI 不得增减】</span></span>
<span class="line"><span>渠道：【微信 / 短信 / 电话】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写 3 个版本的提醒文案（正式 / 亲切 / 极简），每条 80 字内：</span></span>
<span class="line"><span>① 一条不让人反感的开场</span></span>
<span class="line"><span>② 明确提醒事项</span></span>
<span class="line"><span>③ 一个方便对方回应的问句（让他回一个字就行）</span></span>
<span class="line"><span>规矩：不许增加我没写的医疗内容；不许出现用药剂量和频次的建议；不许用&quot;再不注意就晚了&quot;这类恐吓话术。</span></span></code></pre></div><p><strong>它给你</strong>：3 版提醒文案，可直接发。</p><hr><h2 id="_4-·-随访-复诊记录整理" tabindex="-1">4 · 随访 / 复诊记录整理 <a class="header-anchor" href="#_4-·-随访-复诊记录整理" aria-label="Permalink to &quot;4 · 随访 / 复诊记录整理&quot;">​</a></h2><p><strong>什么时候用</strong>：随访记录零散，复诊时要快速看出&quot;这个人和上次比有什么变化&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是一位对象的随访记录（已脱敏，用代号）：</span></span>
<span class="line"><span>【按时间粘贴：日期 + 记录内容】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 整理成时间线（日期 / 事件或指标 / 与上次相比的变化）</span></span>
<span class="line"><span>② 标出&quot;数值或描述明显变化&quot;的点（只做标记，不做判断）</span></span>
<span class="line"><span>③ 列出&quot;记录里缺失、下次随访该补问的信息清单&quot;</span></span>
<span class="line"><span>规矩：只做信息整理与表示，不做任何临床判断、不下结论、不给建议；缺失的信息就写&quot;缺失&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：一条时间线 + 变化标记 + 补问清单。<strong>判断留给医生。</strong></p><hr><h2 id="_5-·-门店-科室服务介绍-说清能做什么、不能做什么" tabindex="-1">5 · 门店 / 科室服务介绍（说清能做什么、不能做什么） <a class="header-anchor" href="#_5-·-门店-科室服务介绍-说清能做什么、不能做什么" aria-label="Permalink to &quot;5 · 门店 / 科室服务介绍（说清能做什么、不能做什么）&quot;">​</a></h2><p><strong>什么时候用</strong>：要做一面墙的介绍、一个公众号页面，或者给新员工看的标准答客话术。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们这里：【药店 / 诊所 / 康复机构 / 体检中心】，位置：【…】</span></span>
<span class="line"><span>我们能提供的服务清单：【…（必须真实、在资质范围内）】</span></span>
<span class="line"><span>我们**不能**做的：【…（例如&quot;不能诊断&quot;&quot;不能开处方&quot;）】</span></span>
<span class="line"><span>最常见的顾客问题：【罗列 5 个】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 写一段 150 字的服务介绍（说清能做什么，也诚实说清不做什么）</span></span>
<span class="line"><span>② 把 5 个常见问题写成&quot;标准答客话术&quot;（每条 60 字内，说清事实 + 引导到正确做法）</span></span>
<span class="line"><span>③ 给我一份&quot;必须转诊 / 必须让他去医院&quot;的判断清单（只列我提供的场景）</span></span>
<span class="line"><span>规矩：不许出现疗效承诺、不许出现&quot;特效/根治/无副作用&quot;；不许编资质。</span></span></code></pre></div><p><strong>它给你</strong>：介绍文案 + 答客话术 + 转诊清单。</p><hr><h2 id="⚠️-这行的红线-比哪个行业都硬" tabindex="-1">⚠️ 这行的红线（比哪个行业都硬） <a class="header-anchor" href="#⚠️-这行的红线-比哪个行业都硬" aria-label="Permalink to &quot;⚠️ 这行的红线（比哪个行业都硬）&quot;">​</a></h2><ol><li><strong>不诊断、不开方、不调药</strong>。AI 给的一切涉及&quot;你这个情况应该……&quot;的话，都不能用。</li><li><strong>不承诺疗效，不用绝对化词</strong>：根治、特效、无副作用、治愈率——出现一个删一个。</li><li><strong>患者信息必须脱敏</strong>：姓名、身份证、手机号、住址、完整病历，<strong>不要粘给 AI</strong>。用代号 + 必要信息。</li><li><strong>科普和科普的边界</strong>：面向公众的科普只讲&quot;普遍情况&quot;，一旦开始说&quot;你该怎么做&quot;，就变成医疗建议了。</li><li><strong>出稿前让人复核</strong>：这一行的内容，发布前请由机构内的专业人员过一遍。AI 只做初稿。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/法律与财税.html">法律与财税</a></strong></p>`,34)])])}const g=a(e,[["render",o]]);export{d as __pageData,g as default};
